const response = $input.first().json;

if (!response.candidates || !response.candidates.length) {
  return [{
    json: {
      parse_error: true,
      gemini_error: response.error || response,
      raw_response: response
    }
  }];
}

let text = response.candidates[0].content.parts[0].text;
text = text.trim().replace(/^```json\n?/, '').replace(/```$/, '');

let invoice;
try {
  invoice = JSON.parse(text);
} catch (e) {
  invoice = { parse_error: true, raw_text: text };
}

const driveFile = $('Google Drive Trigger').first().json;

const lineItemsHtml = (invoice.line_items && invoice.line_items.length)
  ? invoice.line_items.map(li => `
    <tr>
      <td style="padding:6px 10px;border-bottom:1px solid #eee;">${li.description || '-'}</td>
      <td style="padding:6px 10px;border-bottom:1px solid #eee;text-align:center;">${li.quantity || '-'}</td>
      <td style="padding:6px 10px;border-bottom:1px solid #eee;text-align:right;">${li.unit_price || '-'}</td>
      <td style="padding:6px 10px;border-bottom:1px solid #eee;text-align:right;">${li.amount || '-'}</td>
    </tr>`).join('')
  : `<tr><td colspan="4" style="padding:6px 10px;color:#888;">No line items extracted</td></tr>`;

const emailHtml = `
<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;color:#222;">
  <h2 style="color:#2c3e50;border-bottom:2px solid #eee;padding-bottom:8px;">New Invoice Processed</h2>
  <table style="width:100%;border-collapse:collapse;margin:16px 0;font-size:14px;">
    <tr><td style="padding:4px 0;color:#888;width:140px;">Vendor</td><td><b>${invoice.vendor_name || '-'}</b></td></tr>
    <tr><td style="padding:4px 0;color:#888;">Invoice Number</td><td>${invoice.invoice_number || '-'}</td></tr>
    <tr><td style="padding:4px 0;color:#888;">Invoice Date</td><td>${invoice.invoice_date || '-'}</td></tr>
    <tr><td style="padding:4px 0;color:#888;">Due Date</td><td>${invoice.due_date || '-'}</td></tr>
    <tr><td style="padding:4px 0;color:#888;">Total Amount</td><td><b style="font-size:16px;">${invoice.total_amount || '-'} ${invoice.currency || ''}</b></td></tr>
  </table>

  <h3 style="color:#2c3e50;margin-bottom:4px;">Line Items</h3>
  <table style="width:100%;border-collapse:collapse;font-size:13px;">
    <thead>
      <tr style="background:#f5f5f5;">
        <th style="text-align:left;padding:6px 10px;">Description</th>
        <th style="text-align:center;padding:6px 10px;">Qty</th>
        <th style="text-align:right;padding:6px 10px;">Unit Price</th>
        <th style="text-align:right;padding:6px 10px;">Amount</th>
      </tr>
    </thead>
    <tbody>${lineItemsHtml}</tbody>
  </table>

  <p style="margin-top:20px;font-size:13px;color:#555;">
    File: ${driveFile.name}<br>
    <a href="${driveFile.webViewLink || ('https://drive.google.com/file/d/' + driveFile.id + '/view')}" style="color:#3b82f6;">View original invoice in Drive</a>
  </p>
</div>
`;

return [{
  json: {
    ...invoice,
    file_name: driveFile.name,
    file_id: driveFile.id,
    drive_link: driveFile.webViewLink || ('https://drive.google.com/file/d/' + driveFile.id + '/view'),
    processed_at: new Date().toISOString(),
    email_html: emailHtml
  }
}];

const item = $input.first();
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = buffer.toString('base64');

return [{
  json: {
    file_base64: base64,
    file_mime: item.binary.data.mimeType
  }
}];
